fn open_connection(path: &Path) -> Result<Connection, ProjectStoreError> {
    let connection = Connection::open(path)?;
    connection.busy_timeout(std::time::Duration::from_secs(5))?;
    connection.execute_batch(
        "PRAGMA foreign_keys = ON;
         PRAGMA journal_mode = WAL;
         PRAGMA synchronous = NORMAL;",
    )?;
    Ok(connection)
}

fn acquire_database_lock(path: &Path) -> Result<DatabaseLock, ProjectStoreError> {
    let mut lock_path = OsString::from(path.as_os_str());
    lock_path.push(".lock");
    let sidecar = OpenOptions::new()
        .create(true)
        .read(true)
        .truncate(false)
        .write(true)
        .open(PathBuf::from(lock_path))?;
    try_lock_database_file(&sidecar)?;
    let database = OpenOptions::new()
        .create(true)
        .read(true)
        .truncate(false)
        .write(true)
        .open(path)?;
    let identity = acquire_database_identity_lock(&database)?;
    validate_locked_database_path(path, &database)?;
    Ok(DatabaseLock {
        _sidecar: sidecar,
        database,
        _identity: identity,
    })
}

#[cfg(unix)]
fn acquire_database_identity_lock(database: &File) -> Result<File, ProjectStoreError> {
    use std::os::unix::fs::{DirBuilderExt, MetadataExt, OpenOptionsExt};

    let metadata = database.metadata()?;
    let runtime_root = env::var_os("XDG_RUNTIME_DIR")
        .map(PathBuf::from)
        .filter(|path| path.is_absolute())
        .unwrap_or_else(|| {
            PathBuf::from("/tmp").join(format!("yard-{}", rustix::process::geteuid().as_raw()))
        });
    let lock_directory = runtime_root.join("database-locks");
    fs::DirBuilder::new()
        .recursive(true)
        .mode(0o700)
        .create(&lock_directory)?;
    let identity_path =
        lock_directory.join(format!("{:x}-{:x}.lock", metadata.dev(), metadata.ino()));
    let identity = OpenOptions::new()
        .create(true)
        .read(true)
        .truncate(false)
        .write(true)
        .mode(0o600)
        .open(identity_path)?;
    try_lock_database_file(&identity)?;
    Ok(identity)
}

#[cfg(not(unix))]
fn acquire_database_identity_lock(database: &File) -> Result<File, ProjectStoreError> {
    let identity = database.try_clone()?;
    try_lock_database_file(&identity)?;
    Ok(identity)
}

#[cfg(unix)]
fn validate_locked_database_path(path: &Path, database: &File) -> io::Result<()> {
    use std::os::unix::fs::MetadataExt;

    let locked = database.metadata()?;
    let current = fs::metadata(path)?;
    if !current.is_file() || current.dev() != locked.dev() || current.ino() != locked.ino() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "database path '{}' changed while Yard was acquiring ownership",
                path.display()
            ),
        ));
    }
    validate_database_file_identity(path)
}

#[cfg(not(unix))]
fn validate_locked_database_path(path: &Path, _database: &File) -> io::Result<()> {
    validate_database_file_identity(path)
}

fn try_lock_database_file(file: &File) -> Result<(), ProjectStoreError> {
    file.try_lock_exclusive().map_err(|error| {
        if error.kind() == std::io::ErrorKind::WouldBlock {
            ProjectStoreError::DatabaseAlreadyOpen
        } else {
            ProjectStoreError::Io(error)
        }
    })
}

fn recover_interrupted_commands(connection: &mut Connection) -> Result<(), ProjectStoreError> {
    let transaction = connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
    let now = unix_time_ms()?;
    transaction.execute(
        "UPDATE command_acknowledgements
            SET status = 'ambiguous',
                error_message = ?1,
                updated_at_unix_ms = ?2
          WHERE status = 'pending'
            AND command_type = 'profile_allocation'
            AND id IN (
                SELECT command_id
                  FROM profile_allocation_commands
                 WHERE result_assignment_id IS NULL
            )",
        params![
            "Yard restarted during worker profile allocation; fresh runtime inventory is required before the reservation can be released",
            to_i64(now)?,
        ],
    )?;
    transaction.execute(
        "UPDATE command_acknowledgements
            SET status = 'ambiguous',
                error_message = ?1,
                updated_at_unix_ms = ?2
          WHERE status = 'pending'
            AND command_type = 'project_orchestrator_replacement'",
        params![
            "Yard restarted during orchestrator replacement; captured runtimes require inspection and were not retried",
            to_i64(now)?,
        ],
    )?;
    transaction.execute(
        "UPDATE project_orchestrator_replacement_commands
            SET finished_at_unix_ms = ?1
          WHERE finished_at_unix_ms IS NULL
            AND command_id IN (
                SELECT id
                  FROM command_acknowledgements
                 WHERE command_type = 'project_orchestrator_replacement'
                   AND status = 'ambiguous'
            )",
        [to_i64(now)?],
    )?;
    transaction.execute(
        "UPDATE command_acknowledgements
            SET status = 'ambiguous',
                error_message = ?1,
                updated_at_unix_ms = ?2
          WHERE status = 'pending'
            AND command_type IN (
                'assignment_prompt',
                'orchestrator_prompt',
                'yard_orchestrator_prompt',
                'yard_orchestrator_route',
                'coordination_node_prompt',
                'coordination_node_route'
            )",
        params![
            "Yard restarted before prompt acknowledgement; delivery may have occurred and was not retried",
            to_i64(now)?,
        ],
    )?;
    transaction.execute(
        "UPDATE coordination_snapshot_projects
            SET delivery_status = 'ambiguous',
                delivery_error = ?1
          WHERE delivery_status = 'pending'",
        ["Yard restarted before snapshot prompt acknowledgement; delivery may have occurred and was not retried"],
    )?;
    recover_automation_runs(&transaction)?;
    transaction.commit()?;
    Ok(())
}

fn recover_automation_runs(transaction: &Transaction<'_>) -> Result<(), ProjectStoreError> {
    transaction.execute(
        "UPDATE automation_runs
            SET status = 'submitted',
                version = version + 1,
                runtime_status = COALESCE(
                    (
                        SELECT result_runtime_status
                          FROM yard_orchestrator_prompt_commands
                         WHERE command_id = automation_runs.dispatch_command_id
                    ),
                    (
                        SELECT result_runtime_status
                          FROM orchestrator_prompt_commands
                         WHERE command_id = automation_runs.dispatch_command_id
                    ),
                    (
                        SELECT result_runtime_status
                          FROM coordination_node_prompt_commands
                         WHERE command_id = automation_runs.dispatch_command_id
                    ),
                    'submitted'
                ),
                submitted_at_unix_ms = COALESCE(
                    (
                        SELECT submitted_at_unix_ms
                          FROM yard_orchestrator_prompt_commands
                         WHERE command_id = automation_runs.dispatch_command_id
                    ),
                    (
                        SELECT submitted_at_unix_ms
                          FROM orchestrator_prompt_commands
                         WHERE command_id = automation_runs.dispatch_command_id
                    ),
                    (
                        SELECT submitted_at_unix_ms
                          FROM coordination_node_prompt_commands
                         WHERE command_id = automation_runs.dispatch_command_id
                    ),
                    (
                        SELECT updated_at_unix_ms
                          FROM command_acknowledgements
                         WHERE id = automation_runs.dispatch_command_id
                    )
                ),
                updated_at_unix_ms = (
                    SELECT updated_at_unix_ms
                      FROM command_acknowledgements
                     WHERE id = automation_runs.dispatch_command_id
                )
          WHERE status = 'pending'
            AND EXISTS (
                SELECT 1
                  FROM command_acknowledgements
                 WHERE id = automation_runs.dispatch_command_id
                   AND status = 'succeeded'
            )",
        [],
    )?;
    transaction.execute(
        "UPDATE automation_runs
            SET status = (
                    SELECT status
                      FROM command_acknowledgements
                     WHERE id = automation_runs.dispatch_command_id
                ),
                version = version + 1,
                error_message = (
                    SELECT error_message
                      FROM command_acknowledgements
                     WHERE id = automation_runs.dispatch_command_id
                ),
                updated_at_unix_ms = (
                    SELECT updated_at_unix_ms
                      FROM command_acknowledgements
                     WHERE id = automation_runs.dispatch_command_id
                )
          WHERE status = 'pending'
            AND EXISTS (
                SELECT 1
                  FROM command_acknowledgements
                 WHERE id = automation_runs.dispatch_command_id
                   AND status IN ('failed', 'ambiguous')
            )",
        [],
    )?;
    Ok(())
}

#[allow(clippy::too_many_lines)]
fn migrate(connection: &mut Connection) -> Result<(), ProjectStoreError> {
    let mut current: i64 = connection.query_row("PRAGMA user_version", [], |row| row.get(0))?;
    if current > SCHEMA_VERSION {
        return Err(ProjectStoreError::UnsupportedSchema {
            found: current,
            supported: SCHEMA_VERSION,
        });
    }
    if current == 0 {
        let transaction = connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
        transaction.execute_batch(INITIAL_MIGRATION)?;
        transaction.commit()?;
        current = 1;
    }
    if current == 1 {
        let transaction = connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
        transaction.execute_batch(PROFILE_ASSIGNMENT_MIGRATION)?;
        transaction.commit()?;
        current = 2;
    }
    if current == 2 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            transaction.execute_batch(COMPLETION_RECEIPT_MIGRATION)?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
        current = 3;
    }
    if current == 3 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            transaction.execute_batch(ASSIGNMENT_PROMPT_MIGRATION)?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
        current = 4;
    }
    if current == 4 {
        let transaction = connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
        transaction.execute_batch(RUNTIME_RECONCILIATION_MIGRATION)?;
        transaction.commit()?;
        current = 5;
    }
    if current == 5 {
        let transaction = connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
        transaction.execute_batch(RECONCILIATION_WATERMARK_MIGRATION)?;
        transaction.commit()?;
        current = 6;
    }
    if current == 6 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            transaction.execute_batch(WORKER_ALLOCATION_MIGRATION)?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
        current = 7;
    }
    if current == 7 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            transaction.execute_batch(PROFILE_PROJECT_CREATION_MIGRATION)?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
        current = 8;
    }
    if current == 8 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            transaction.execute_batch(WORKER_HANDOFF_MIGRATION)?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
        current = 9;
    }
    if current == 9 {
        let transaction = connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
        transaction.execute_batch(RUNTIME_CLEANUP_MIGRATION)?;
        transaction.commit()?;
        current = 10;
    }
    if current == 10 {
        let transaction = connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
        transaction.execute_batch(ARTIFACT_MIGRATION)?;
        transaction.commit()?;
        current = 11;
    }
    if current == 11 {
        let transaction = connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
        transaction.execute_batch(WORKSPACE_PROJECT_CREATION_MIGRATION)?;
        transaction.commit()?;
        current = 12;
    }
    if current == 12 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            transaction.execute_batch(ORCHESTRATOR_PROMPT_MIGRATION)?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
        current = 13;
    }
    if current == 13 {
        if worker_session_end_schema_exists(connection)? {
            if command_acknowledgements_support_worker_session_end(connection)? {
                connection.execute_batch("PRAGMA user_version = 14;")?;
            } else {
                connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
                let migration = (|| {
                    let transaction =
                        connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
                    transaction.execute_batch(WORKER_SESSION_END_ACK_REPAIR_MIGRATION)?;
                    ensure_foreign_keys(&transaction)?;
                    transaction.commit()?;
                    Ok::<(), ProjectStoreError>(())
                })();
                let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
                migration?;
                foreign_keys?;
            }
            ensure_foreign_keys(connection)?;
            current = 14;
        } else {
            connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
            let migration = (|| {
                let transaction =
                    connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
                transaction.execute_batch(WORKER_SESSION_END_MIGRATION)?;
                ensure_foreign_keys(&transaction)?;
                transaction.commit()?;
                Ok::<(), ProjectStoreError>(())
            })();
            let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
            migration?;
            foreign_keys?;
            current = 14;
        }
    }
    if current == 14 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            transaction.execute_batch(YARD_ORCHESTRATOR_MIGRATION)?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
        current = 15;
    }
    if current == 15 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            transaction.execute_batch(COORDINATION_MIGRATION)?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
        current = 16;
    }
    if current == 16 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            transaction.execute_batch(COORDINATION_NODES_MIGRATION)?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
        current = 17;
    }
    if current == 17 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            transaction.execute_batch(AUTOMATIONS_MIGRATION)?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
        current = 18;
    }
    if current == 18 {
        let transaction = connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
        transaction.execute_batch(TOKEN_SPEND_SETTINGS_MIGRATION)?;
        transaction.commit()?;
        current = 19;
    }
    if current == 19 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            transaction.execute_batch(ORCHESTRATOR_REPLACEMENT_MIGRATION)?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
        current = 20;
    }
    if current == 20 {
        let transaction = connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
        transaction.execute_batch(AGENT_PROFILES_MIGRATION)?;
        backfill_agent_profile_revisions(&transaction)?;
        ensure_foreign_keys(&transaction)?;
        transaction.commit()?;
        current = 21;
    }
    if current == 21 {
        let transaction = connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
        transaction.execute_batch(ORCHESTRATOR_WORKFLOW_PROFILE_MIGRATION)?;
        orchestrator_workflow_profile_store::seed_factory_profile(&transaction)?;
        ensure_foreign_keys(&transaction)?;
        transaction.commit()?;
        current = 22;
    }
    if current == 22 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            transaction.execute_batch(PROJECT_ORCHESTRATOR_TRANSFER_MIGRATION)?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
        current = 23;
    }
    if current == 23 {
        let transaction = connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
        transaction.execute_batch(ORCHESTRATOR_REPLACEMENT_RECOVERY_MIGRATION)?;
        ensure_foreign_keys(&transaction)?;
        transaction.commit()?;
        current = 24;
    }
    if current == 24 {
        let transaction = connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
        transaction.execute_batch(FINAL_BACKEND_SAFETY_MIGRATION)?;
        ensure_foreign_keys(&transaction)?;
        transaction.commit()?;
        current = 25;
    }
    if current == 25 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            let lineage = classify_schema_v25(&transaction)?;
            ensure_schema_v25_common_rebuild_shapes(&transaction)?;
            match lineage {
                SchemaV25Lineage::BackendSafety => {
                    transaction.execute_batch(PROVIDER_NEUTRAL_WORKFLOW_PROFILES_MIGRATION)?;
                    orchestrator_workflow_profile_store::upgrade_provider_neutral_profile(
                        &transaction,
                        false,
                    )?;
                }
                SchemaV25Lineage::ProviderNeutralWorkflow => {
                    transaction.execute_batch(FINAL_BACKEND_SAFETY_MIGRATION)?;
                }
                SchemaV25Lineage::Combined => {}
            }
            if classify_schema_v25(&transaction)? != SchemaV25Lineage::Combined {
                return invalid_schema_v25(
                    "migration did not produce the complete combined schema",
                );
            }
            ensure_schema_v25_component_shapes(&transaction)?;
            ensure_schema_v25_workflow_invariants(&transaction)?;
            transaction.execute_batch(PROVIDER_NEUTRAL_WORKFLOW_PROFILE_INTEGRITY_MIGRATION)?;
            orchestrator_workflow_profile_store::activate_complete_provider_neutral_profile(
                &transaction,
            )?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
        current = 26;
    }
    if current == 26 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            transaction.execute_batch(PROJECT_ARCHIVING_MIGRATION)?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
        current = 27;
    }
    if current == 27 {
        connection.execute_batch("PRAGMA foreign_keys = OFF;")?;
        let migration = (|| {
            let transaction =
                connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
            transaction.execute_batch(VISIBILITY_DELETIONS_MIGRATION)?;
            ensure_foreign_keys(&transaction)?;
            transaction.commit()?;
            Ok::<(), ProjectStoreError>(())
        })();
        let foreign_keys = connection.execute_batch("PRAGMA foreign_keys = ON;");
        migration?;
        foreign_keys?;
    }
    ensure_foreign_keys(connection)?;
    Ok(())
}

