fn project_has_active_work(
    connection: &Connection,
    project_id: &str,
) -> Result<bool, ProjectStoreError> {
    connection
        .query_row(
            "SELECT EXISTS (
                SELECT 1
                  FROM assignments
                 WHERE project_id = ?1
                   AND lifecycle IN ('allocating', 'active', 'handing_off')
                UNION ALL
                SELECT 1
                  FROM profile_allocation_commands allocation
                  JOIN command_acknowledgements command
                    ON command.id = allocation.command_id
                 WHERE allocation.project_id = ?1
                   AND command.status IN ('pending', 'ambiguous')
                UNION ALL
                SELECT 1
                  FROM worker_allocation_commands allocation
                  JOIN command_acknowledgements command
                    ON command.id = allocation.command_id
                 WHERE allocation.project_id = ?1
                   AND command.status IN ('pending', 'ambiguous')
                UNION ALL
                SELECT 1
                  FROM automations
                 WHERE scope_project_id = ?1
                UNION ALL
                SELECT 1
                  FROM automation_selected_projects
                 WHERE project_id = ?1
                UNION ALL
                SELECT 1
                  FROM automation_runs
                 WHERE scope_project_id = ?1
                   AND status IN ('pending', 'ambiguous')
                UNION ALL
                SELECT 1
                  FROM automation_run_projects run_project
                  JOIN automation_runs run
                    ON run.id = run_project.run_id
                 WHERE run_project.project_id = ?1
                   AND run.status IN ('pending', 'ambiguous')
             )",
            [project_id],
            |row| row.get(0),
        )
        .map_err(Into::into)
}

fn project_exists(connection: &Connection, project_id: &str) -> Result<bool, ProjectStoreError> {
    connection
        .query_row(
            "SELECT EXISTS (
                SELECT 1
                  FROM projects project
                  JOIN project_workspace_bindings binding
                    ON binding.project_id = project.id
                 WHERE project.id = ?1
             )",
            [project_id],
            |row| row.get(0),
        )
        .map_err(Into::into)
}

fn select_project_relationship(
    connection: &Connection,
    relationship_id: &str,
) -> Result<Option<ProjectRelationship>, ProjectStoreError> {
    connection
        .query_row(
            "SELECT id, source_project_id, target_project_id, kind,
                    version, created_by, created_at_unix_ms,
                    updated_at_unix_ms
               FROM project_relationships
              WHERE id = ?1",
            [relationship_id],
            project_relationship_from_row,
        )
        .optional()
        .map_err(Into::into)
}

fn project_relationship_from_row(row: &Row<'_>) -> rusqlite::Result<ProjectRelationship> {
    Ok(ProjectRelationship {
        id: row.get(0)?,
        source_project_id: row.get(1)?,
        target_project_id: row.get(2)?,
        kind: project_relationship_kind_from_row(row, 3)?,
        version: row_u64(row, 4)?,
        created_by: row.get(5)?,
        created_at_unix_ms: row_u64(row, 6)?,
        updated_at_unix_ms: row_u64(row, 7)?,
    })
}

