    #[allow(clippy::too_many_lines)]
    fn downgrade_provider_neutral_workflow_schema_to_v25(connection: &Connection) {
        connection
            .execute_batch(
                "PRAGMA foreign_keys = OFF;
                 DROP TABLE IF EXISTS deleted_projects;
                 DROP TABLE IF EXISTS deleted_workers;
                 DROP TABLE IF EXISTS archived_projects;
                 DROP TRIGGER orchestrator_workflow_profile_revision_immutable_update;
                 DROP TRIGGER orchestrator_workflow_profile_revision_immutable_delete;
                 DROP TRIGGER profile_project_creation_workflow_pin_insert;
                 DROP TRIGGER profile_project_creation_workflow_pin_update;
                 DROP TRIGGER workspace_project_creation_workflow_pin_insert;
                 DROP TRIGGER workspace_project_creation_workflow_pin_update;
                 DROP TABLE project_orchestrator_replacement_workflow_pins;

                 CREATE TABLE orchestrator_workflow_profile_revisions_v25 (
                    version INTEGER PRIMARY KEY NOT NULL CHECK (version > 0),
                    instructions_markdown TEXT NOT NULL
                        CHECK (length(instructions_markdown) > 0),
                    monitor_interval_ms INTEGER NOT NULL
                        CHECK (monitor_interval_ms > 0),
                    source TEXT NOT NULL
                        CHECK (source IN ('factory', 'user', 'reset')),
                    updated_by TEXT NOT NULL CHECK (length(updated_by) > 0),
                    created_at_unix_ms INTEGER NOT NULL
                 ) STRICT;
                 INSERT INTO orchestrator_workflow_profile_revisions_v25
                 SELECT version, instructions_markdown, monitor_interval_ms,
                        source, updated_by, created_at_unix_ms
                   FROM orchestrator_workflow_profile_revisions
                  WHERE profile_id = 'yard:standard-orchestrator';

                 CREATE TABLE orchestrator_workflow_profile_current_v25 (
                    singleton_id INTEGER PRIMARY KEY NOT NULL
                        CHECK (singleton_id = 1),
                    current_version INTEGER NOT NULL
                        REFERENCES orchestrator_workflow_profile_revisions_v25(version)
                        ON DELETE RESTRICT,
                    updated_at_unix_ms INTEGER NOT NULL
                 ) STRICT;
                 INSERT INTO orchestrator_workflow_profile_current_v25
                 SELECT singleton_id, current_version, updated_at_unix_ms
                   FROM orchestrator_workflow_profile_current;

                 CREATE TABLE yard_orchestrator_v25 (
                    singleton_id INTEGER PRIMARY KEY NOT NULL
                        CHECK (singleton_id = 1),
                    worker_id TEXT UNIQUE
                        REFERENCES workers(id) ON DELETE RESTRICT,
                    version INTEGER NOT NULL CHECK (version > 0),
                    created_at_unix_ms INTEGER NOT NULL,
                    updated_at_unix_ms INTEGER NOT NULL,
                    workflow_profile_version INTEGER
                        REFERENCES orchestrator_workflow_profile_revisions_v25(version)
                        ON DELETE RESTRICT
                 ) STRICT;
                 INSERT INTO yard_orchestrator_v25
                 SELECT singleton_id, worker_id, version, created_at_unix_ms,
                        updated_at_unix_ms, workflow_profile_version
                   FROM yard_orchestrator;

                 CREATE TABLE yard_orchestrator_configure_commands_v25 (
                    command_id TEXT PRIMARY KEY NOT NULL
                        REFERENCES command_acknowledgements(id) ON DELETE RESTRICT,
                    worker_id TEXT NOT NULL
                        REFERENCES workers(id) ON DELETE RESTRICT,
                    expected_worker_version INTEGER NOT NULL
                        CHECK (expected_worker_version > 0),
                    expected_orchestrator_version INTEGER NOT NULL
                        CHECK (expected_orchestrator_version > 0),
                    replaced_worker_id TEXT
                        REFERENCES workers(id) ON DELETE RESTRICT,
                    result_orchestrator_version INTEGER NOT NULL
                        CHECK (result_orchestrator_version > 0),
                    finished_at_unix_ms INTEGER NOT NULL,
                    workflow_profile_version INTEGER
                        REFERENCES orchestrator_workflow_profile_revisions_v25(version)
                        ON DELETE RESTRICT
                 ) STRICT;
                 INSERT INTO yard_orchestrator_configure_commands_v25
                 SELECT command_id, worker_id, expected_worker_version,
                        expected_orchestrator_version, replaced_worker_id,
                        result_orchestrator_version, finished_at_unix_ms,
                        workflow_profile_version
                   FROM yard_orchestrator_configure_commands;

                 DROP TABLE project_workflow_profile_pins;
                 DROP TABLE orchestrator_workflow_profiles;
                 ALTER TABLE profile_project_creation_commands
                    DROP COLUMN workflow_profile_version;
                 ALTER TABLE profile_project_creation_commands
                    DROP COLUMN workflow_profile_id;
                 ALTER TABLE workspace_project_creation_commands
                    DROP COLUMN workflow_profile_version;
                 ALTER TABLE workspace_project_creation_commands
                    DROP COLUMN workflow_profile_id;
                 DROP TABLE orchestrator_workflow_profile_current;
                 DROP TABLE yard_orchestrator_configure_commands;
                 DROP TABLE yard_orchestrator;
                 DROP TABLE orchestrator_workflow_profile_revisions;

                 ALTER TABLE orchestrator_workflow_profile_revisions_v25
                    RENAME TO orchestrator_workflow_profile_revisions;
                 ALTER TABLE orchestrator_workflow_profile_current_v25
                    RENAME TO orchestrator_workflow_profile_current;
                 ALTER TABLE yard_orchestrator_v25 RENAME TO yard_orchestrator;
                 ALTER TABLE yard_orchestrator_configure_commands_v25
                    RENAME TO yard_orchestrator_configure_commands;
                 PRAGMA user_version = 25;
                 PRAGMA foreign_keys = ON;",
            )
            .unwrap();
    }

    #[allow(clippy::too_many_lines)]
    fn drop_automation_schema_for_downgrade(connection: &Connection) {
        downgrade_final_backend_safety_schema_to_v24(connection);
        connection
            .execute_batch(
                "PRAGMA foreign_keys = OFF;
                 DROP TABLE project_orchestrator_transfer_runtime_bindings;
                 DROP TABLE project_orchestrator_transfer_commands;
                 ALTER TABLE yard_orchestrator_configure_commands
                    DROP COLUMN workflow_profile_version;
                 ALTER TABLE yard_orchestrator
                    DROP COLUMN workflow_profile_version;
                 DROP TABLE orchestrator_workflow_profile_current;
                 DROP TABLE orchestrator_workflow_profile_revisions;
                 DROP TABLE agent_profile_revisions;
                 DROP TABLE automatic_summary_request_watermarks;
                 DROP TABLE token_spend_settings;
                 DROP TABLE orchestrator_replacement_runtime_bindings;
                 DROP TABLE project_orchestrator_replacement_commands;
                 DELETE FROM runtime_cleanup_jobs
                  WHERE command_id IN (
                    SELECT id FROM command_acknowledgements
                     WHERE command_type = 'project_orchestrator_replacement'
                  );
                 CREATE TABLE runtime_cleanup_jobs_v18 (
                    id TEXT PRIMARY KEY NOT NULL,
                    command_id TEXT NOT NULL
                        REFERENCES command_acknowledgements(id)
                        ON DELETE RESTRICT,
                    worker_id TEXT NOT NULL
                        REFERENCES workers(id) ON DELETE RESTRICT,
                    reason TEXT NOT NULL CHECK (
                        reason IN (
                            'handoff_source',
                            'replaced_orchestrator',
                            'worker_session_end'
                        )
                    ),
                    adapter TEXT NOT NULL,
                    runtime_session TEXT NOT NULL,
                    runtime_workspace_id TEXT NOT NULL,
                    terminal_id TEXT NOT NULL,
                    tab_id TEXT,
                    pane_id TEXT NOT NULL,
                    owns_tab INTEGER NOT NULL CHECK (owns_tab IN (0, 1)),
                    status TEXT NOT NULL
                        CHECK (status IN ('pending', 'succeeded')),
                    attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
                    last_error TEXT,
                    next_attempt_at_unix_ms INTEGER NOT NULL,
                    created_at_unix_ms INTEGER NOT NULL,
                    updated_at_unix_ms INTEGER NOT NULL,
                    completed_at_unix_ms INTEGER,
                    UNIQUE (adapter, runtime_session, terminal_id),
                    CHECK (
                        (
                            status = 'pending'
                            AND completed_at_unix_ms IS NULL
                        )
                        OR (
                            status = 'succeeded'
                            AND completed_at_unix_ms IS NOT NULL
                        )
                    ),
                    CHECK (owns_tab = 0 OR tab_id IS NOT NULL)
                 ) STRICT;
                 INSERT INTO runtime_cleanup_jobs_v18 (
                    id, command_id, worker_id, reason, adapter,
                    runtime_session, runtime_workspace_id, terminal_id,
                    tab_id, pane_id, owns_tab, status, attempts, last_error,
                    next_attempt_at_unix_ms, created_at_unix_ms,
                    updated_at_unix_ms, completed_at_unix_ms
                 )
                 SELECT id, command_id, worker_id, reason, adapter,
                        runtime_session, runtime_workspace_id, terminal_id,
                        tab_id, pane_id, owns_tab, status, attempts, last_error,
                        next_attempt_at_unix_ms, created_at_unix_ms,
                        updated_at_unix_ms, completed_at_unix_ms
                   FROM runtime_cleanup_jobs;
                 DROP TABLE runtime_cleanup_jobs;
                 ALTER TABLE runtime_cleanup_jobs_v18
                    RENAME TO runtime_cleanup_jobs;
                 CREATE TABLE command_acknowledgements_v19 (
                    id TEXT PRIMARY KEY NOT NULL,
                    command_type TEXT NOT NULL CHECK (
                        command_type IN (
                            'profile_allocation',
                            'worker_allocation',
                            'worker_handoff',
                            'profile_project_creation',
                            'completion_receipt',
                            'assignment_prompt',
                            'orchestrator_prompt',
                            'worker_session_end',
                            'yard_orchestrator_configure',
                            'yard_orchestrator_prompt',
                            'project_relationship_create',
                            'project_relationship_delete',
                            'yard_orchestrator_route',
                            'coordination_node_create',
                            'coordination_node_update',
                            'coordination_node_placement',
                            'coordination_node_provision',
                            'coordination_node_prompt',
                            'coordination_node_route',
                            'coordination_snapshot_request',
                            'automation_create',
                            'automation_update',
                            'automation_placement',
                            'automation_pause',
                            'automation_run_now'
                        )
                    ),
                    actor TEXT NOT NULL,
                    status TEXT NOT NULL CHECK (
                        status IN (
                            'pending',
                            'succeeded',
                            'failed',
                            'ambiguous'
                        )
                    ),
                    error_message TEXT,
                    created_at_unix_ms INTEGER NOT NULL,
                    updated_at_unix_ms INTEGER NOT NULL,
                    CHECK (
                        (
                            status IN ('failed', 'ambiguous')
                            AND error_message IS NOT NULL
                        )
                        OR (
                            status NOT IN ('failed', 'ambiguous')
                            AND error_message IS NULL
                        )
                    )
                 ) STRICT;
                 INSERT INTO command_acknowledgements_v19
                 SELECT id, command_type, actor, status, error_message,
                        created_at_unix_ms, updated_at_unix_ms
                   FROM command_acknowledgements
                  WHERE command_type <> 'project_orchestrator_replacement';
                 DROP TABLE command_acknowledgements;
                 ALTER TABLE command_acknowledgements_v19
                    RENAME TO command_acknowledgements;
                 CREATE INDEX pending_runtime_cleanup_jobs
                    ON runtime_cleanup_jobs (
                        next_attempt_at_unix_ms,
                        created_at_unix_ms
                    )
                    WHERE status = 'pending';
                 DROP TABLE automation_run_now_commands;
                 DROP TABLE automation_run_projects;
                 DROP TABLE automation_runs;
                 DROP TABLE automation_pause_commands;
                 DROP TABLE automation_placement_commands;
                 DROP TABLE automation_update_command_projects;
                 DROP TABLE automation_update_commands;
                 DROP TABLE automation_create_command_projects;
                 DROP TABLE automation_create_commands;
                 DROP TABLE automation_selected_projects;
                 DROP TABLE automation_placements;
                 DROP TABLE automations;",
            )
            .unwrap();
    }

    fn downgrade_store_to_v18(path: &std::path::Path) {
        let connection = Connection::open(path).unwrap();
        connection
            .execute_batch("PRAGMA foreign_keys = OFF;")
            .unwrap();
        drop_automation_schema_for_downgrade(&connection);
        connection.execute_batch(AUTOMATIONS_MIGRATION).unwrap();
        connection
            .execute_batch("PRAGMA foreign_keys = ON;")
            .unwrap();
        let version: i64 = connection
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .unwrap();
        assert_eq!(version, 18);
    }

    #[tokio::test]
